package com.alxt.SoundPad;
import android.app.*;import android.content.*;import android.content.pm.ServiceInfo;import android.media.*;import android.media.projection.*;import android.os.*;import java.io.*;
public class CaptureService extends Service { MediaProjection p; AudioRecord r; volatile boolean run; Thread t; public int onStartCommand(Intent i,int f,int id){if(i==null)return 2;if("STOP".equals(i.getAction())){stop();return 2;}createNotification();startForeground(2,new Notification.Builder(this,"sp").setContentTitle("SoundPad recording").setSmallIcon(android.R.drawable.ic_btn_speak_now).build(),ServiceInfo.FOREGROUND_SERVICE_TYPE_MEDIA_PROJECTION);try{p=((MediaProjectionManager)getSystemService(MEDIA_PROJECTION_SERVICE)).getMediaProjection(i.getIntExtra("code",0),(Intent)i.getParcelableExtra("data"));AudioPlaybackCaptureConfiguration c=new AudioPlaybackCaptureConfiguration.Builder(p).addMatchingUsage(AudioAttributes.USAGE_MEDIA).addMatchingUsage(AudioAttributes.USAGE_GAME).build();AudioFormat a=new AudioFormat.Builder().setEncoding(2).setSampleRate(44100).setChannelMask(12).build();r=new AudioRecord.Builder().setAudioFormat(a).setBufferSizeInBytes(16384).setAudioPlaybackCaptureConfig(c).build();r.startRecording();run=true;t=new Thread(()->{File out=new File(getExternalFilesDir(null),"capture.pcm");try(FileOutputStream o=new FileOutputStream(out)){byte[] b=new byte[8192];while(run){int n=r.read(b,0,b.length);if(n>0)o.write(b,0,n);}}catch(Exception e){}stopSelf();});t.start();}catch(Exception e){stop();stopSelf();}return 2;}void createNotification(){if(Build.VERSION.SDK_INT>=26){((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).createNotificationChannel(new NotificationChannel("sp","SoundPad",NotificationManager.IMPORTANCE_LOW));}}void stop(){run=false;try{if(r!=null){r.stop();r.release();}}catch(Exception e){}r=null;try{if(p!=null)p.stop();}catch(Exception e){}p=null;stopForeground(true);stopSelf();}public void onDestroy(){stop();super.onDestroy();}public IBinder onBind(Intent i){return null;}}
